def transform(grid):
    # Grid lines at row/col intervals outline large uniform tiles. At the four
    # corners of a tile, matching marker colors indicate its output color;
    # otherwise use the tile's dominant interior color.
    h, w = len(grid), len(grid[0])
    # A separator row contains the dominant background almost everywhere;
    # a separator column is similarly uniform. Ignore up to a few marker exceptions.
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
