    # Collapse thick or adjacent separators to one representative coordinate.
    def collapse(indices):
        groups = []
        for x in indices:
            if not groups or x > groups[-1][-1] + 1:
                groups.append([x])
            else:
                groups[-1].append(x)
        return [g[len(g) // 2] for g in groups]

