            base = Counter(interior).most_common(1)[0][0]
            corners = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
            value = corners[0] if corners[0] != bg and all(x == corners[0] for x in corners) else base
            row.append(value)
        if row:
            output.append(row)
    return output
